<?php require __DIR__.'/includes/bootstrap.php';$items=cart();if(!$items)redirect('/cart.php');$tot=cart_totals();$errors=[];$success=null;if(is_post()){verify_csrf();$name=trim((string)post('customer_name'));$phone=trim((string)post('customer_phone'));$email=trim((string)post('customer_email'));$city=trim((string)post('city'));$area=trim((string)post('area'));$address=trim((string)post('address'));$method=(string)post('payment_method','cod');$notes=trim((string)post('notes'));if($name===''||$phone===''||$city===''||$address==='')$errors[]='Please complete required delivery fields.';if(!in_array($method,['cod','bkash','nagad','rocket','sslcommerz'],true))$errors[]='Invalid payment method.';if(!$errors){$pdo=db();try{$pdo->beginTransaction();$ord='PR-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$st=$pdo->prepare('INSERT INTO orders(order_number,customer_id,customer_name,customer_phone,customer_email,customer_address,city,area,subtotal,discount,shipping_cost,total,payment_method,payment_status,order_status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$ord,user()['id']??null,$name,$phone,$email,$address,$city,$area,$tot['subtotal'],$tot['discount'],$tot['shipping'],$tot['total'],$method,'pending','pending',$notes]);$oid=(int)$pdo->lastInsertId();$oi=$pdo->prepare('INSERT INTO order_items(order_id,product_id,variant_id,product_name,sku,quantity,unit_price,total,size,color,custom_name,custom_number,printing_charge) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$dec=$pdo->prepare('UPDATE variants SET stock=stock-? WHERE id=?');foreach($items as $it){$oi->execute([$oid,$it['product_id'],$it['variant_id'],$it['name'],$it['sku'],$it['qty'],$it['price'],$it['line_total'],$it['size'],$it['color'],$it['custom_name'],$it['custom_number'],$it['printing_charge']]);if($it['variant_id']){$dec->execute([$it['qty'],$it['variant_id']]);}}$pdo->commit();$_SESSION['cart']=[];unset($_SESSION['coupon_discount']);$success=$ord;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Could not create order. '.$e->getMessage();}}}if($success)redirect('/order-success.php?order='.urlencode($success));$title='Checkout';require __DIR__.'/includes/header.php';?><div class="max-w-6xl mx-auto px-3 sm:px-5 py-8"><div class="mb-6"><div class="text-xs tracking-[.2em] text-slate-400 font-black">CHECKOUT</div><h1 class="text-3xl font-black">1-Page Checkout</h1></div><?php foreach($errors as $x):?><div class="mb-4 p-4 rounded-xl bg-rose-50 border border-rose-100 text-rose-700"><?=e($x)?></div><?php endforeach;?><form method="post" class="grid lg:grid-cols-[1fr_360px] gap-6"><?=csrf_input()?><div class="space-y-5"><div class="bg-white border rounded-2xl p-5"><div class="font-black text-lg">Contact Information</div><div class="grid sm:grid-cols-2 gap-3 mt-4"><input required name="customer_name" value="<?=e(post('customer_name',user()['name']??''))?>" placeholder="Full name" class="rounded-xl border-slate-200"><input required name="customer_phone" value="<?=e(post('customer_phone',user()['phone']??''))?>" placeholder="Phone number" class="rounded-xl border-slate-200"><input type="email" name="customer_email" value="<?=e(post('customer_email',user()['email']??''))?>" placeholder="Email (optional)" class="sm:col-span-2 rounded-xl border-slate-200"></div></div><div class="bg-white border rounded-2xl p-5"><div class="font-black text-lg">Shipping Address</div><div class="grid sm:grid-cols-2 gap-3 mt-4"><input required name="city" placeholder="City" value="<?=e(post('city'))?>" class="rounded-xl border-slate-200"><input name="area" placeholder="Area / Thana" value="<?=e(post('area'))?>" class="rounded-xl border-slate-200"><textarea required name="address" placeholder="Full address" class="sm:col-span-2 min-h-28 rounded-xl border-slate-200"><?=e(post('address'))?></textarea></div></div><div class="bg-white border rounded-2xl p-5"><div class="font-black text-lg">Payment</div><div class="grid grid-cols-2 sm:grid-cols-5 gap-2 mt-4"><?php foreach(['cod'=>'Cash on Delivery','bkash'=>'bKash','nagad'=>'Nagad','rocket'=>'Rocket','sslcommerz'=>'SSLCommerz'] as $k=>$v):?><label><input type="radio" name="payment_method" value="<?=$k?>" class="peer sr-only" <?=($k===post('payment_method','cod')?'checked':'')?>><span class="block p-3 border rounded-xl text-center text-sm font-bold peer-checked:bg-slate-950 peer-checked:text-white"><?=e($v)?></span></label><?php endforeach;?></div><textarea name="notes" class="w-full mt-4 rounded-xl border-slate-200 min-h-20" placeholder="Order note (optional)"><?=e(post('notes'))?></textarea></div></div><div class="bg-white border rounded-2xl p-5 h-fit sticky top-28"><div class="font-black text-lg">Order Summary</div><?php foreach($items as $it):?><div class="flex gap-3 mt-4"><img src="<?=e(image_or_placeholder($it['image'],$it['name']))?>" class="w-14 h-14 rounded-xl object-cover"><div class="flex-1 min-w-0 text-sm"><div class="font-bold line-clamp-2"><?=e($it['name'])?></div><div class="text-xs text-slate-400">Qty <?=$it['qty']?></div></div><b><?=money($it['line_total'])?></b></div><?php endforeach;?><div class="border-t mt-4 pt-4 space-y-2 text-sm"><div class="flex justify-between"><span>Subtotal</span><b><?=money($tot['subtotal'])?></b></div><div class="flex justify-between"><span>Delivery</span><b><?=money($tot['shipping'])?></b></div><div class="flex justify-between"><span>Discount</span><b>-<?=money($tot['discount'])?></b></div><div class="flex justify-between border-t pt-2 text-lg"><span class="font-black">Total</span><b><?=money($tot['total'])?></b></div></div><button class="w-full mt-5 py-3 rounded-xl bg-slate-950 text-white font-black">Place Order · <?=money($tot['total'])?></button></div></form></div><?php require __DIR__.'/includes/footer.php';?>
